import re, os

for root, dirs, files in os.walk('src'):
    for f in files:
        if not f.endswith('.rs'):
            continue
        path = os.path.join(root, f)
        with open(path) as fh:
            content = fh.read()

        # Find #[cfg(test)] and #[test] blocks to skip
        # Simple approach: check each line
        lines = content.split('\n')
        in_test = False
        for i, line in enumerate(lines, 1):
            stripped = line.strip()
            if stripped.startswith('#[cfg(test)]'):
                in_test = True
            if in_test:
                continue
            if 'prompt' in line.lower() and 'unwrap' in line:
                print(f'{path}:{i}: {line.strip()}')
"

